# of the model id).
function New-AgyArgv {
    param([string]$Model, [string]$Schema = '', [string]$Thread = '', [string]$NativeEffort = '')
    $a = @('-p=', '--input-format', 'stream-json', '--output-format', 'stream-json', '--model', $Model)
