}
$purposeText = @{

2009: $extraEvents = New-Object System.Collections.Generic.List[string]
2152: $extraEvents.Add("handoffs/$retryEventsName")
2335: $extraEvents.Add("handoffs/$repairEventsName")
2386: if (-not $isCodex -and $extraEvents.Count -gt 0 -and -not $treeProblem) {
2515: if ($extraEvents.Count -gt 0) { $furtherTurns = '; further turns: ' + (($extraEvents.ToArray() | ForEach-Object { '`' + $_ + '`' }) -join ', ') }

                        if ($repairSurvivors.Count -gt 0) {
                            $repairProblem = "timeout after $repairTimeout s (process tree killed; $($repairSurvivors.Count) processes survived: pid $($repairSurvivors -join ', '))"
                            $keepPending = $true
                            try {
